use super::refs::parse_track;
use super::tests::oid;
use super::*;
use crate::DomainError;
use proptest::prelude::*;

// Real git 2.43.0 output, generated by `testdata/refs.sh` (`sh refs.sh testdata`) in temporary
// repos with `GIT_CONFIG_GLOBAL=/dev/null`, `GIT_CONFIG_NOSYSTEM=1` and fixed dates. The command
// is always
//
// ```sh
// git for-each-ref \
//     '--format=%(refname)%00%(objectname)%00%(*objectname)%00%(upstream)%00%(upstream:track,nobracket)%00%(symref)%00' \
//     refs/heads/ refs/remotes/ refs/tags/ refs/stash
// ```
//
// that is, the arguments of [`REFS_ARGS`].

/// Clone of a bare remote with: `main` level, `forward` (ahead 2), `back` (behind 1),
/// `both` (ahead 1, behind 2), `gone` (upstream deleted, gone), `on-main` (local
/// upstream `refs/heads/main`), branches without upstream `feature/new-interface`, `café` and
/// `latin-\xff` (non-UTF-8), the symbolic ref `refs/heads/alias`, symbolic `origin/HEAD`,
/// `origin/remote-only`, lightweight tag `v0.1`, annotated `v1.0`, annotated tag of an annotated one
/// `v1.0-double`, lightweight on a tree `tree`, `refs/notes/commits` and a stash.
const REFS: &[u8] = include_bytes!("testdata/refs.bin");
/// Repo just created with `git init`: zero bytes.
const EMPTY: &[u8] = include_bytes!("testdata/refs-empty.bin");
/// `main` with a `branch.main.merge` that contains a newline: `%(upstream)` reports it as is.
const UPSTREAM_NEWLINE: &[u8] = include_bytes!("testdata/refs-upstream-newline.bin");
/// The script that generates the files: it must use the same format as [`REFS_FORMAT`].
const SCRIPT: &str = include_str!("testdata/refs.sh");

const BASE: &str = "bd2d8c9e18e2e352d32888c352e83b36addd5e08";
const FORWARD: &str = "de58f806d585c7b14dda9c74dcc94f6282bcdd8a";

fn parse(input: &[u8]) -> Vec<RefInfo> {
    parse_refs(input).expect("valid real output")
}

fn reason(err: DomainError) -> String {
    match err {
        DomainError::InvalidGitOutput { command, reason } => {
            assert_eq!(command, "for-each-ref");
            reason
        }
        other => panic!("unexpected error: {other:?}"),
    }
}

fn find<'a>(refs: &'a [RefInfo], name: &str) -> &'a RefInfo {
    refs.iter()
        .find(|r| r.name == name)
        .unwrap_or_else(|| panic!("missing {name}"))
}

fn branch(name: &str, target: &str, upstream: Option<(&str, Option<u32>, Option<u32>)>) -> RefInfo {
    RefInfo {
        name: name.into(),
        kind: RefKind::LocalBranch,
        target: oid(target),
        tag_object: None,
        upstream: upstream.map(|(name, ahead, behind)| Upstream {
            name: name.into(),
            ahead,
            behind,
        }),
    }
}

fn plain(name: &str, kind: RefKind, target: &str) -> RefInfo {
    RefInfo {
        name: name.into(),
        kind,
        target: oid(target),
        tag_object: None,
        upstream: None,
    }
}

#[test]
fn the_script_uses_the_constant_format() {
    assert!(SCRIPT.contains(&format!("'--format={REFS_FORMAT}'")));
    assert_eq!(REFS_ARGS[0], format!("--format={REFS_FORMAT}"));
    assert!(SCRIPT.contains("refs/heads/ refs/remotes/ refs/tags/ refs/stash"));
    assert_eq!(
        &REFS_ARGS[1..],
        ["refs/heads/", "refs/remotes/", "refs/tags/", "refs/stash"]
    );
    assert_eq!(REFS_FORMAT.matches("%00").count(), REFS_FIELDS);
}

#[test]
fn names_and_kinds_in_git_order() {
    let refs = parse(REFS);
    let names: Vec<(&str, RefKind)> = refs.iter().map(|r| (r.name.as_str(), r.kind)).collect();
    use RefKind::*;
    assert_eq!(
        names,
        [
            ("refs/heads/back", LocalBranch),
            ("refs/heads/both", LocalBranch),
            ("refs/heads/caf\u{e9}", LocalBranch),
            ("refs/heads/feature/new-interface", LocalBranch),
            ("refs/heads/forward", LocalBranch),
            ("refs/heads/gone", LocalBranch),
            ("refs/heads/main", LocalBranch),
            ("refs/heads/on-main", LocalBranch),
            ("refs/remotes/origin/back", RemoteBranch),
            ("refs/remotes/origin/both", RemoteBranch),
            ("refs/remotes/origin/forward", RemoteBranch),
            ("refs/remotes/origin/main", RemoteBranch),
            ("refs/remotes/origin/only-remote", RemoteBranch),
            ("refs/stash", Stash),
            ("refs/tags/tree", Tag),
            ("refs/tags/v0.1", Tag),
            ("refs/tags/v1.0", Tag),
            ("refs/tags/v1.0-double", Tag),
        ]
    );
}

#[test]
fn ignored_symbolic_and_non_utf8() {
    let refs = parse(REFS);
    // They are in the output, but the parser discards them.
    for raw in [
        &b"refs/heads/alias\0"[..],
        b"refs/remotes/origin/HEAD\0",
        b"refs/heads/latin-\xff\0",
    ] {
        assert!(REFS.windows(raw.len()).any(|w| w == raw));
    }
    assert!(!refs.iter().any(|r| r.name == "refs/heads/alias"));
    assert!(!refs.iter().any(|r| r.name.ends_with("/HEAD")));
    assert!(!refs.iter().any(|r| r.name.starts_with("refs/heads/latin-")));
    // The patterns exclude the notes.
    assert!(!REFS.windows(11).any(|w| w == b"refs/notes/"));
}

#[test]
fn local_branches_with_upstream() {
    let refs = parse(REFS);
    let origin = |b: &str| format!("refs/remotes/origin/{b}");
    let cases = [
        branch(
            "refs/heads/main",
            BASE,
            Some((&origin("main"), Some(0), Some(0))),
        ),
        branch(
            "refs/heads/forward",
            FORWARD,
            Some((&origin("forward"), Some(2), Some(0))),
        ),
        branch(
            "refs/heads/back",
            BASE,
            Some((&origin("back"), Some(0), Some(1))),
        ),
        branch(
            "refs/heads/both",
            "bdfa39ec2e006e1901b327815c082a8eb18e924a",
            Some((&origin("both"), Some(1), Some(2))),
        ),
        branch("refs/heads/gone", BASE, Some((&origin("gone"), None, None))),
        branch(
            "refs/heads/on-main",
            BASE,
            Some(("refs/heads/main", Some(0), Some(0))),
        ),
        branch("refs/heads/feature/new-interface", BASE, None),
        branch("refs/heads/caf\u{e9}", BASE, None),
    ];
    for expected in cases {
        assert_eq!(find(&refs, &expected.name), &expected);
    }
    assert_eq!(
        find(&refs, "refs/heads/feature/new-interface").short_name(),
        "feature/new-interface"
    );
    assert_eq!(
        find(&refs, "refs/heads/caf\u{e9}").short_name(),
        "caf\u{e9}"
    );
}

#[test]
fn remotes_and_stash() {
    let refs = parse(REFS);
    for expected in [
        plain("refs/remotes/origin/main", RefKind::RemoteBranch, BASE),
        plain("refs/remotes/origin/forward", RefKind::RemoteBranch, BASE),
        plain(
            "refs/remotes/origin/both",
            RefKind::RemoteBranch,
            "d4ab3a2f2042cb627bf11c019bb955c79288fdfd",
        ),
        plain(
            "refs/remotes/origin/back",
            RefKind::RemoteBranch,
            "668ab055e8a83137c674615da141642a825ac945",
        ),
        plain(
            "refs/remotes/origin/only-remote",
            RefKind::RemoteBranch,
            "fb813ddb69cef568d6e5ab82ba76bae92ace5d02",
        ),
        plain(
            "refs/stash",
            RefKind::Stash,
            "d49b4cc9233974217cf57e465add844869a1732e",
        ),
    ] {
        assert_eq!(find(&refs, &expected.name), &expected);
    }
    assert_eq!(
        find(&refs, "refs/remotes/origin/only-remote").short_name(),
        "origin/only-remote"
    );
}

#[test]
fn light_and_annotated_tags() {
    let refs = parse(REFS);
    assert_eq!(
        find(&refs, "refs/tags/v0.1"),
        &plain("refs/tags/v0.1", RefKind::Tag, BASE)
    );
    // Annotated: target is the commit, tag_object the tag object.
    let v1 = find(&refs, "refs/tags/v1.0");
    assert_eq!(v1.target, oid(FORWARD));
    assert_eq!(
        v1.tag_object,
        Some(oid("41c758a0a1fbaccf7a1a33d22a9a1d9acda352ac"))
    );
    // Tag of a tag: git gives the id of v1.0, the parser follows it down to the commit.
    let double = find(&refs, "refs/tags/v1.0-double");
    assert_eq!(double.target, oid(FORWARD));
    assert_eq!(
        double.tag_object,
        Some(oid("30cc6f902a51af1b13c644a7ac29024fb0e71834"))
    );
    // Lightweight on a tree: the target is the tree.
    assert_eq!(
        find(&refs, "refs/tags/tree"),
        &plain(
            "refs/tags/tree",
            RefKind::Tag,
            "7bee507cb7f5aa4dce34e6962366eeea27935c74"
        )
    );
}

#[test]
fn empty_repo() {
    assert_eq!(EMPTY, b"");
    assert_eq!(parse(EMPTY), []);
}

#[test]
fn upstream_with_newline_in_the_name() {
    assert_eq!(
        parse(UPSTREAM_NEWLINE),
        [branch(
            "refs/heads/main",
            "ae057ba31fb9143aeb323d3ef28aead528b5ba52",
            Some(("refs/remotes/origin/line\nnew", None, None)),
        )]
    );
}

#[test]
fn tag_of_tag_without_the_inner_tag_stays_at_the_inner_tag() {
    let a = "1111111111111111111111111111111111111111";
    let b = "2222222222222222222222222222222222222222";
    let input = format!("refs/tags/x\0{a}\0{b}\0\0\0\0\n");
    let refs = parse(input.as_bytes());
    assert_eq!(refs[0].target, oid(b));
    assert_eq!(refs[0].tag_object, Some(oid(a)));
}

#[test]
fn unknown_kinds_ignored() {
    let input = format!(
        "refs/notes/commits\0{BASE}\0\0\0\0\0\nrefs/stash/x\0{BASE}\0\0\0\0\0\nHEAD\0{BASE}\0\0\0\0\0\nrefs/heads/a\0{BASE}\0\0\0\0\0\n"
    );
    let refs = parse(input.as_bytes());
    assert_eq!(refs, [branch("refs/heads/a", BASE, None)]);
}

#[test]
fn ahead_behind() {
    for (track, expected) in [
        (&b""[..], Some((Some(0), Some(0)))),
        (b"gone", Some((None, None))),
        (b"ahead 3", Some((Some(3), Some(0)))),
        (b"behind 4", Some((Some(0), Some(4)))),
        (b"ahead 1, behind 2", Some((Some(1), Some(2)))),
        (b"ahead 4294967295", Some((Some(u32::MAX), Some(0)))),
        (b"ahead 4294967296", None),
        (b"ahead", None),
        (b"ahead -1", None),
        (b"[ahead 1]", None),
        (b"ahead 1,behind 2", None),
        (b"ahead 1, behind", None),
        (b"behind 2, ahead 1", None),
        (b"ahead 1, behind 2, x", None),
        (b"level", None),
    ] {
        assert_eq!(
            parse_track(track),
            expected,
            "{}",
            String::from_utf8_lossy(track)
        );
    }
}

#[test]
fn errors() {
    let ok = format!("refs/heads/a\0{BASE}\0\0\0\0\0\n");
    let cases: Vec<(Vec<u8>, &str)> = vec![
        (
            ok.as_bytes()[..ok.len() - 1].to_vec(),
            "does not end with NUL and newline",
        ),
        (
            b"refs/heads/a\n".to_vec(),
            "does not end with NUL and newline",
        ),
        (
            format!("refs/heads/a\0{BASE}\0\0\n").into_bytes(),
            "record 1: 3 fields instead of 6 (missing upstream",
        ),
        (
            format!("{ok}refs/heads/b\0\0\n").into_bytes(),
            "record 2: 2 fields instead of 6 (missing id pointed",
        ),
        (
            format!("refs/heads/a\0{BASE}\0\0\0\0\0refs/heads/b\0{BASE}\0\0\0\0\0\n").into_bytes(),
            "record 2: missing newline",
        ),
        (b"refs/heads/a\0abc\0\0\0\0\0\n".to_vec(), "record 1: id"),
        (
            format!("refs/heads/a\0{BASE}\0xyz\0\0\0\0\n").into_bytes(),
            "record 1: id pointed to by the tag",
        ),
        (
            format!("\0{BASE}\0\0\0\0\0\n").into_bytes(),
            "record 1: empty name (%(refname))",
        ),
        (
            format!("refs/heads/a\0{BASE}\0\0refs/remotes/o/a\0forward 1\0\0\n").into_bytes(),
            "invalid ahead/behind (%(upstream:track,nobracket)): `forward 1`",
        ),
        (
            format!("refs/heads/a\0{BASE}\0\0\0ahead 1\0\0\n").into_bytes(),
            "is `ahead 1` but upstream (%(upstream)) is empty",
        ),
    ];
    for (input, expected) in cases {
        let r = reason(parse_refs(&input).expect_err(&String::from_utf8_lossy(&input)));
        assert!(r.contains(expected), "`{r}` does not contain `{expected}`");
    }
}

/// Rewrites the refs in git's format: the opposite of [`parse_refs`].
fn render(refs: &[RefInfo]) -> Vec<u8> {
    let mut out = Vec::new();
    for r in refs {
        let (object, peeled) = match r.tag_object {
            Some(tag) => (tag, r.target.to_string()),
            None => (r.target, String::new()),
        };
        let (upstream, track) = match &r.upstream {
            None => (String::new(), String::new()),
            Some(u) => {
                let track = match (u.ahead, u.behind) {
                    (None, _) | (_, None) => "gone".to_owned(),
                    (Some(0), Some(0)) => String::new(),
                    (Some(a), Some(0)) => format!("ahead {a}"),
                    (Some(0), Some(b)) => format!("behind {b}"),
                    (Some(a), Some(b)) => format!("ahead {a}, behind {b}"),
                };
                (u.name.clone(), track)
            }
        };
        out.extend_from_slice(
            format!("{}\0{object}\0{peeled}\0{upstream}\0{track}\0\0\n", r.name).as_bytes(),
        );
    }
    out
}

fn arb_oid() -> impl Strategy<Value = Oid> {
    any::<[u8; 20]>().prop_map(Oid::from_bytes)
}

fn arb_ref() -> impl Strategy<Value = RefInfo> {
    let local = (
        "[a-zA-Z0-9éï/._-]{1,20}",
        arb_oid(),
        prop::option::of((
            "refs/(heads|remotes/[a-z]{1,5})/[a-z/]{1,10}( \n[a-z]{0,3})?",
            prop::option::of((any::<u32>(), any::<u32>())),
        )),
    )
        .prop_map(|(name, target, upstream)| RefInfo {
            name: format!("refs/heads/{name}"),
            kind: RefKind::LocalBranch,
            target,
            tag_object: None,
            upstream: upstream.map(|(name, ab)| Upstream {
                name,
                ahead: ab.map(|(a, _)| a),
                behind: ab.map(|(_, b)| b),
            }),
        });
    let remote =
        ("[a-z]{1,5}/[a-zA-Z0-9/._-]{1,20}", arb_oid()).prop_map(|(name, target)| RefInfo {
            name: format!("refs/remotes/{name}"),
            kind: RefKind::RemoteBranch,
            target,
            tag_object: None,
            upstream: None,
        });
    let tag = (
        "[a-zA-Z0-9/._-]{1,20}",
        arb_oid(),
        prop::option::of(arb_oid()),
    )
        .prop_map(|(name, target, tag_object)| RefInfo {
            name: format!("refs/tags/{name}"),
            kind: RefKind::Tag,
            target,
            tag_object,
            upstream: None,
        });
    let stash = arb_oid().prop_map(|target| RefInfo {
        name: "refs/stash".into(),
        kind: RefKind::Stash,
        target,
        tag_object: None,
        upstream: None,
    });
    prop_oneof![local, remote, tag, stash]
}

proptest! {
    #[test]
    fn round_trip_of_the_format(refs in prop::collection::vec(arb_ref(), 0..8)) {
        let parsed = parse_refs(&render(&refs)).map_err(|e| TestCaseError::fail(e.to_string()))?;
        prop_assert_eq!(parsed, refs);
    }

    #[test]
    fn round_trip_json(refs in prop::collection::vec(arb_ref(), 0..8)) {
        let json = serde_json::to_string(&refs).map_err(|e| TestCaseError::fail(e.to_string()))?;
        let back: Vec<RefInfo> =
            serde_json::from_str(&json).map_err(|e| TestCaseError::fail(e.to_string()))?;
        prop_assert_eq!(back, refs);
    }

    #[test]
    fn no_panic_on_arbitrary_bytes(input in prop::collection::vec(any::<u8>(), 0..400)) {
        let _ = parse_refs(&input);
    }

    #[test]
    fn no_panic_on_modified_real_output(
        cut in 0..REFS.len(),
        pos in 0..REFS.len(),
        byte in any::<u8>(),
    ) {
        let _ = parse_refs(&REFS[..cut]);
        let mut changed = REFS.to_vec();
        changed[pos] = byte;
        let _ = parse_refs(&changed);
    }

    #[test]
    fn truncated_output_not_silently_accepted(cut in 1..REFS.len()) {
        // A cut can only fall on a record boundary, after `\0\n`: there the result is a
        // prefix of the full list; elsewhere it is an error.
        let full = parse(REFS);
        match parse_refs(&REFS[..cut]) {
            Ok(refs) => {
                prop_assert!(REFS[..cut].ends_with(b"\0\n"));
                prop_assert!(full.starts_with(&refs));
            }
            Err(e) => { reason(e); }
        }
    }
}
